}

/* 👑 智能触发：只要存在未读消息，返回键自动拉长到 76px */
body:has(.nuo-chat-header-unread-num) .header-btn-back {
  width: 76px !important;
}

/* 返回键贴纸 */
.header-btn-back::after {
  content: ""; position: absolute; inset: 0;
  background-image: url('https://imgbed.heliar.top/i/MpjBV14ad4s7XFLj_IMG_5823.png');
  background-size: 25px;                
